public class Traversal_shouldTraverse_TriageGen0Test {

  @Mock private NodeTraversal mockTraversal;
  @Mock private Node mockNode;
  @Mock private Node mockParent;

  private ScopedAliases.Traversal traversal;

  @Before
  public void setUp() {
    MockitoAnnotations.initMocks(this);
    traversal = new ScopedAliases.Traversal();
  }

  /**
   * Test case: Node is not a function.
   * Expected: shouldTraverse returns true.
   */
  @Test
  public void testShouldTraverse_NotAFunction() {
    when(mockNode.isFunction()).thenReturn(false);

    assertTrue(traversal.shouldTraverse(mockTraversal, mockNode, mockParent));
  }

  /**
   * Test case: Node is a function but not in global scope.
   * Expected: shouldTraverse returns true.
   */
  @Test
  public void testShouldTraverse_FunctionNotInGlobalScope() {
    when(mockNode.isFunction()).thenReturn(true);
    when(mockTraversal.inGlobalScope()).thenReturn(false);

    assertTrue(traversal.shouldTraverse(mockTraversal, mockNode, mockParent));
  }

  /**
   * Test case: Node is a function in global scope, and parent is null.
   * Expected: shouldTraverse returns false (matches if (parent == null || !isCallToScopeMethod(parent))).
   */
  @Test
  public void testShouldTraverse_FunctionInGlobalScopeWithNullParent() {
    when(mockNode.isFunction()).thenReturn(true);
    when(mockTraversal.inGlobalScope()).thenReturn(true);

    assertFalse(traversal.shouldTraverse(mockTraversal, mockNode, null));
  }

  /**
   * Test case: Node is a function in global scope, parent is not a scope method call.
   * Expected: shouldTraverse returns false.
   */
  @Test
  public void testShouldTraverse_FunctionInGlobalScopeNotScopeMethod() {
    when(mockNode.isFunction()).thenReturn(true);
    when(mockTraversal.inGlobalScope()).thenReturn(true);
